-- Authenticated, read-only room artwork; no Auth accounts or live membership.
create table toti_private.community_room_materials (
 id uuid primary key,
 content jsonb not null check (jsonb_typeof(content)='object'),
 cover_asset text generated always as (content->>'cover_asset') stored unique,
 published boolean not null default false,
 created_at timestamptz not null default now()
);
alter table toti_private.community_room_materials enable row level security;
revoke all on toti_private.community_room_materials from public,anon,authenticated;
