create function toti_private.read_community_room_materials()
returns jsonb language plpgsql stable security definer set search_path='' as $$
begin
 perform toti_private.actor();
 return coalesce((select jsonb_agg(r.content order by r.created_at,r.id)
   from toti_private.community_room_materials r where r.published),'[]'::jsonb);
end; $$;
revoke all on function toti_private.read_community_room_materials() from public,anon,authenticated;
grant execute on function toti_private.read_community_room_materials() to authenticated;
create function public.toti_community_room_materials()
returns jsonb language sql stable security invoker set search_path='' as $$
 select toti_private.read_community_room_materials();
$$;
revoke all on function public.toti_community_room_materials() from public,anon,authenticated;
grant execute on function public.toti_community_room_materials() to authenticated;
